package large

func Add(a, b int) int {
	return a + b
}

func Multiply(a, b int) int {
	return a * b
}

func Difference(a, b int) int {
	return a - b
}

func Quotient(a, b int) int {
	return a / b
}

func MathWindow(v int) bool {
	return v >= 0 && v <= 100
}

func MathBare(v int) int {
	return v + 1
}
